    class BcdFreq32(ReadWriteKaitaiStruct):
        """A frequency as u32 little-endian packed BCD, eight digits, 10 Hz units (so the most
        significant nibble is hundreds of MHz). 0xFFFFFFFF means unused.
        
        .. seealso::
           DM32.00.01.048 freq_calibration_interpolate_single @0x0301b130
        
        
        .. seealso::
           infamy/DM32-Protocol-Spec 06-ENCODING.md "BCD Frequency Encoding" (same codec as channel frequencies)
        """
        def __init__(self, _io=None, _parent=None, _root=None):
            super(Dm32Calibration.BcdFreq32, self).__init__(_io)
            self._parent = _parent
            self._root = _root

        def _read(self):
            self.raw = self._io.read_u4le()
            self._dirty = False


        def _fetch_instances(self):
            pass


        def _write__seq(self, io=None):
            super(Dm32Calibration.BcdFreq32, self)._write__seq(io)
            self._io.write_u4le(self.raw)


        def _check(self):
            self._dirty = False

        @property
        def freq_10hz(self):
            """Decoded frequency in units of 10 Hz (meaningless when is_blank).
            
            .. seealso::
               infamy/DM32-Protocol-Spec 06-ENCODING.md "BCD Frequency Encoding"
            """
            if hasattr(self, '_m_freq_10hz'):
                return self._m_freq_10hz

            self._m_freq_10hz = (((((((self.raw >> 28 & 15) * 10000000 + (self.raw >> 24 & 15) * 1000000) + (self.raw >> 20 & 15) * 100000) + (self.raw >> 16 & 15) * 10000) + (self.raw >> 12 & 15) * 1000) + (self.raw >> 8 & 15) * 100) + (self.raw >> 4 & 15) * 10) + (self.raw & 15)
            return getattr(self, '_m_freq_10hz', None)

        def _invalidate_freq_10hz(self):
            del self._m_freq_10hz
        @property
        def is_blank(self):
            """True for an erased (unused) entry.
            
            .. seealso::
               four-unit comparison
            """
            if hasattr(self, '_m_is_blank'):
                return self._m_is_blank

            self._m_is_blank = self.raw == 4294967295
            return getattr(self, '_m_is_blank', None)

        def _invalidate_is_blank(self):
            del self._m_is_blank

    class Points5(ReadWriteKaitaiStruct):
        """Five one-byte calibration points, one per breakpoint of the band. The firmware reads them
        with 2-byte reads at (base + i), i = bracket index, and passes the two bytes as the low and
        high value to linear_interpolate_freq_calibration. Index 4 (top of band) is clamped before
        use, but the addressable extent is still 6 bytes, so the 6th byte belongs to whatever
        follows (instance `reach`). Copying exactly 5 bytes per table drops that overlap.
        
        .. seealso::
           DM32.00.01.048 freq_calibration_interpolate_selected @0x0301b424
        """
        def __init__(self, base, _io=None, _parent=None, _root=None):
            super(Dm32Calibration.Points5, self).__init__(_io)
            self._parent = _parent
            self._root = _root
            self.base = base
            self._should_write_reach = False
            self.reach__enabled = True

        def _read(self):
            self.points = []
            for i in range(5):
                self.points.append(self._io.read_u1())

            self._dirty = False


        def _fetch_instances(self):
            pass
            for i in range(len(self.points)):
                pass

            _ = self.reach
            if hasattr(self, '_m_reach'):
                pass



        def _write__seq(self, io=None):
            super(Dm32Calibration.Points5, self)._write__seq(io)
            self._should_write_reach = self.reach__enabled
            for i in range(len(self.points)):
                pass
                self._io.write_u1(self.points[i])



        def _check(self):
            if len(self.points) != 5:
                raise kaitaistruct.ConsistencyError(u"points", 5, len(self.points))
            for i in range(len(self.points)):
                pass

            if self.reach__enabled:
                pass
                if len(self._m_reach) != 6:
                    raise kaitaistruct.ConsistencyError(u"reach", 6, len(self._m_reach))

            self._dirty = False

        @property
        def reach(self):
            """The six bytes the firmware's overlapping 2-byte reads can reach (points plus the next byte).
            
            .. seealso::
               DM32.00.01.048 freq_calibration_interpolate_selected @0x0301b424
            """
            if self._should_write_reach:
                self._write_reach()
            if hasattr(self, '_m_reach'):
                return self._m_reach

            if not self.reach__enabled:
                return None

            io = self._parent._io
            _pos = io.pos()
            io.seek(self.base)
            self._m_reach = io.read_bytes(6)
            io.seek(_pos)
            return getattr(self, '_m_reach', None)

        @reach.setter
        def reach(self, v):
            self._dirty = True
            self._m_reach = v

        def _write_reach(self):
            self._should_write_reach = False
            io = self._parent._io
            _pos = io.pos()
            io.seek(self.base)
            io.write_bytes(self._m_reach)
            io.seek(_pos)



